"""Background report jobs: interactors PDF and pairing biddings CSV."""
import csv
import threading
import uuid
from pathlib import Path

from fpdf import FPDF

from .config import settings
from .db import SessionLocal
from .models import Bidding, Edict, Slot, Submission, SubmissionAdvisor, User
from .sqlalchemy import select  # noqa: F401  (placeholder, removed below)

JOBS: dict[str, dict] = {}


def new_job(kind: str) -> str:
    job_id = uuid.uuid4().hex
    JOBS[job_id] = {"kind": kind, "path": None}
    return job_id


def _finish(job_id: str, path: str) -> None:
    JOBS[job_id]["path"] = path


def _edict_row(edict_id: int):
    db = SessionLocal()
    try:
        edict = db.get(Edict, edict_id)
        return edict
    finally:
        db.close()


def _interactors(db, edict_id: int) -> list[User]:
    """Users that interacted with the edict by comment, favorite, label or note."""
    user_ids: set[int] = set()
    for model in (Comment, Favorite, Label, PrivateNote):
        pass
    from sqlalchemy import select as _select
    from .models import Comment, Favorite, Label, PrivateNote
    for model in (Comment, Favorite, Label, PrivateNote):
        rows = db.execute(
            _select(model.user_id)
            .join(Submission, model.submission_id == Submission.id)
            .where(Submission.edict_id == edict_id)
        ).scalars().all()
        user_ids.update(rows)
    if not user_ids:
        return []
    return db.query(User).filter(User.id.in_(user_ids)).order_by(User.id).all()


def _generate_pdf(job_id: str, edict_id: int, options: dict) -> None:
    from .models import Comment, Favorite, Label, PrivateNote  # noqa: F401

    db = SessionLocal()
    try:
        edict = db.get(Edict, edict_id)
        submissions = (
            db.query(Submission).filter(Submission.edict_id == edict_id).all()
        )
        approved = [s for s in submissions if s.stats == "approved"]
        refused = [s for s in submissions if s.stats == "refused"]
        underreview = [s for s in submissions if s.stats == "underreview"]
        waitlist = [s for s in submissions if s.stats == "waitlist"]
        interactors = _interactors(db, edict_id)

        advisors: dict[int, str] = {}
        for sub in approved:
            adv = (
                db.query(User)
                .join(SubmissionAdvisor, SubmissionAdvisor.user_id == User.id)
                .filter(SubmissionAdvisor.submission_id == sub.id)
                .first()
            )
            advisors[sub.id] = adv.name if adv else ""

        pdf = FPDF()
        pdf.add_page()
        for img in ("assets/logo.png", "assets/usp.png"):
            if Path(img).exists():
                pdf.image(img, w=40)
        pdf.set_font("Helvetica", "B", 16)
        pdf.cell(0, 10, f"Relatorio do Edital {edict.title if edict else ''}", ln=1)
        pdf.set_font("Helvetica", size=12)
        if edict:
            pdf.cell(0, 10, f"Ano: {edict.year}", ln=1)

        if options.get("general_statistics"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Estatisticas gerais", ln=1)
            pdf.set_font("Helvetica", size=12)
            finalized = [s for s in submissions]
            pdf.cell(0, 8, f"Candidaturas finalizadas: {len(finalized)}", ln=1)
            pdf.cell(0, 8, "Candidaturas em preenchimento: 0", ln=1)

        if options.get("approved"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Aprovados", ln=1)
            pdf.set_font("Helvetica", size=12)
            for sub in approved:
                line = f"{sub.name} <{sub.email}>"
                if options.get("list_of_advisors"):
                    line += f" - Orientador: {advisors.get(sub.id, '')}"
                pdf.cell(0, 8, line, ln=1)

        if options.get("refused"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Reprovados", ln=1)
            pdf.set_font("Helvetica", size=12)
            for sub in refused:
                pdf.cell(0, 8, f"{sub.name} <{sub.email}>", ln=1)

        if options.get("underreview"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Em revisao", ln=1)
            pdf.set_font("Helvetica", size=12)
            for sub in underreview + waitlist:
                pdf.cell(0, 8, f"{sub.name} <{sub.email}>", ln=1)

        if options.get("relation"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Relacao de aprovados e orientadores", ln=1)
            pdf.set_font("Helvetica", size=12)
            for sub in approved:
                pdf.cell(
                    0, 8,
                    f"{sub.name} - {advisors.get(sub.id, '')}",
                    ln=1,
                )

        if options.get("show_emails"):
            pdf.set_font("Helvetica", "B", 12)
            pdf.cell(0, 10, "Lista de e-mails", ln=1)
            pdf.set_font("Helvetica", size=12)
            for user in interactors:
                pdf.cell(0, 8, f"{user.name} <{user.email}>", ln=1)

        path = str(Path(settings.TMP_DIR) / f"{job_id}.pdf")
        pdf.output(path)
        _finish(job_id, path)
    finally:
        db.close()


def _generate_csv(job_id: str, edict_id: int) -> None:
    db = SessionLocal()
    try:
        submissions = (
            db.query(Submission)
            .filter(Submission.edict_id == edict_id)
            .order_by(Submission.id)
            .all()
        )
        biddings = (
            db.query(Bidding)
            .join(Submission, Bidding.submission_id == Submission.id)
            .filter(Submission.edict_id == edict_id)
            .all()
        )
        teachers = sorted({b.user_id for b in biddings})
        users = {u.id: u for u in db.query(User).filter(User.id.in_(teachers))} if teachers else {}
        slots = {
            s.user_id: s.amount
            for s in db.query(Slot).filter(Slot.edict_id == edict_id)
        }
        by_user: dict[int, dict[int, str]] = {}
        for b in biddings:
            by_user.setdefault(b.user_id, {})[b.submission_id] = b.bidding

        path = Path(settings.TMP_DIR) / f"{job_id}.csv"
        with open(path, "w", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(
                ["#"] + [users[t].email or "" for t in teachers]
            )
            writer.writerow(["slots"] + [slots.get(t, "0") for t in teachers])
            for sub in submissions:
                writer.writerow(
                    [sub.email]
                    + [by_user.get(t, {}).get(sub.id, "") for t in teachers]
                )
        _finish(job_id, str(path))
    finally:
        db.close()


def start_pdf_job(edict_id: int, options: dict) -> str:
    job_id = new_job("pdf")
    threading.Thread(
        target=_generate_pdf, args=(job_id, edict_id, options), daemon=True
    ).start()
    return job_id


def start_csv_job(edict_id: int) -> str:
    job_id = new_job("csv")
    threading.Thread(
        target=_generate_csv, args=(job_id, edict_id), daemon=True
    ).start()
    return job_id

"""Authentication routes: dev shortcut login and Senha Única OAuth."""
from datetime import datetime
from pathlib import Path
from urllib.parse import parse_qs, urljoin

import requests
from fastapi import APIRouter, Depends, HTTPException, Request
from oauthlib.oauth1 import Client

from ..config import settings
from ..db import get_db
from ..models import User
from ..security import get_user
from ..schemas import LoginSchema

router = APIRouter(tags=["auth"])


def _load_whitelist() -> set[str]:
    path = Path(settings.WHITELIST_FILE)
    if not path.exists():
        return set()
    values: set[str] = set()
    for line in path.read_text().splitlines():
        for part in line.split(","):
            part = part.strip()
            if part:
                values.add(part)
    return values


def _user_payload(user: User) -> dict:
    return {
        "id": user.id,
        "name": user.name,
        "email": user.email,
        "nusp": user.nusp,
        "role": user.role,
    }


@router.get("/auth/login")
def login(request: Request, db=Depends(get_db)):
    user = get_user(request, db)
    if user is None:
        raise HTTPException(status_code=401, detail="Not authenticated")
    return _user_payload(user)


def _oauth_client(**kwargs) -> Client:
    return Client(
        settings.SENHAUNICA_CONSUMER_KEY,
        client_secret=settings.SENHAUNICA_CONSUMER_SECRET,
        **kwargs,
    )


def _resource_url(resource: str) -> str:
    if resource.startswith("http://") or resource.startswith("https://"):
        return resource
    return urljoin(settings.SENHAUNICA_OAUTH_HOST.rstrip("/") + "/", resource.lstrip("/"))


@router.post("/auth/login/senhaunica")
def login_senhaunica(request: Request, db=Depends(get_db)):
    params = request.query_params
    oauth_token = params.get("oauth_token")
    oauth_verifier = params.get("oauth_verifier")

    if not oauth_token:
        # First step: obtain a request token and redirect to the provider.
        callback = (
            f"{settings.BASE_URL.rstrip('/')}/auth/login/senhaunica"
            if not settings.SENHAUNICA_CALLBACK_ID
            else settings.SENHAUNICA_CALLBACK_ID
        )
        client = _oauth_client(callback_uri=callback)
        uri, headers, body = client.sign(
            _resource_url(settings.SENHAUNICA_REQUEST_TOKEN_RESOURCE),
            http_method="POST",
        )
        try:
            resp = requests.post(uri, headers=headers, data=body, timeout=30)
        except requests.RequestException:
            raise HTTPException(status_code=500, detail="OAuth request failed")
        if resp.status_code != 200:
            raise HTTPException(status_code=500, detail="OAuth request failed")
        data = parse_qs(resp.text)
        try:
            token = data["oauth_token"][0]
            secret = data["oauth_token_secret"][0]
        except (KeyError, IndexError):
            raise HTTPException(status_code=500, detail="OAuth request failed")
        request.session["oauth_token"] = token
        request.session["oauth_secret"] = secret
        authorize = _resource_url(settings.SENHAUNICA_AUTHORIZE_URL)
        return {"redirect_to": f"{authorize}?oauth_token={token}"}

    # Callback: exchange the request token for the access token.
    secret = request.session.get("oauth_secret")
    if (
        not secret
        or request.session.get("oauth_token") != oauth_token
        or not oauth_verifier
    ):
        raise HTTPException(status_code=401, detail="Invalid OAuth callback")

    client = _oauth_client(
        resource_owner_key=oauth_token,
        resource_owner_secret=secret,
        verifier=oauth_verifier,
    )
    uri, headers, body = client.sign(
        _resource_url(settings.SENHAUNICA_ACCESS_TOKEN_RESOURCE),
        http_method="POST",
    )
    try:
        resp = requests.post(uri, headers=headers, data=body, timeout=30)
    except requests.RequestException:
        raise HTTPException(status_code=500, detail="OAuth token exchange failed")
    if resp.status_code != 200:
        raise HTTPException(status_code=500, detail="OAuth token exchange failed")
    data = {k: v[0] for k, v in parse_qs(resp.text).items() if v}

    nome = (
        data.get("nome")
        or data.get("nomeUsuario")
        or data.get("nome_usuario")
        or data.get("name")
        or ""
    )
    email = (
        data.get("email")
        or data.get("emailUsuario")
        or data.get("email_usuario")
        or ""
    )
    nusp = (
        data.get("nusp")
        or data.get("codpes")
        or data.get("login")
        or data.get("oauth_token")
        or ""
    )

    whitelist = _load_whitelist()
    if whitelist and nusp not in whitelist:
        raise HTTPException(status_code=403, detail="NUSP not authorized")

    user = None
    if email:
        user = db.query(User).filter(User.email == email).first()
    if user is None:
        user = User(
            name=nome or email or nusp,
            email=email or None,
            nusp=nusp or None,
            role="teacher",
            created_at=datetime.utcnow(),
        )
        db.add(user)
        db.commit()
    request.session["user_id"] = user.id
    request.session.pop("oauth_secret", None)
    request.session.pop("oauth_token", None)
    return _user_payload(user)

